export default JSON.parse(
  "{\n  \"workId\": \"mo-zi\",\n  \"chapter\": {\n    \"id\": \"mo-zi_ch-39\",\n    \"workId\": \"mo-zi\",\n    \"order\": 39,\n    \"title\": \"非儒下\",\n    \"difficulty\": 5,\n    \"estimatedMinutes\": 10,\n    \"passageIds\": [\n      \"mo-zi_ch-39_p-1\",\n      \"mo-zi_ch-39_p-2\",\n      \"mo-zi_ch-39_p-3\",\n      \"mo-zi_ch-39_p-4\",\n      \"mo-zi_ch-39_p-5\",\n      \"mo-zi_ch-39_p-6\",\n      \"mo-zi_ch-39_p-7\",\n      \"mo-zi_ch-39_p-8\",\n      \"mo-zi_ch-39_p-9\",\n      \"mo-zi_ch-39_p-10\",\n      \"mo-zi_ch-39_p-11\",\n      \"mo-zi_ch-39_p-12\"\n    ],\n    \"tags\": [\n      \"墨家\",\n      \"墨子\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"mo-zi_ch-39_p-1\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 1,\n      \"canonicalText\": \"儒者曰：「親親有術，尊賢有等。」言親疏尊卑之異也。其禮曰：「喪父母三年，妻，後子三年，伯父叔父弟兄庶子其，戚族人五月。」若以親疏為歲月之數，則親者多而疏者少矣，是妻後子與父同也。若以尊卑為歲月數，則是尊其妻子與父母同，而親伯父宗兄而卑子也，逆孰大焉。其親死，列屍弗斂，登屋窺井，挑鼠穴，探滌器，而求其人矣。以為實在則贛愚甚矣；如其亡也必求焉，偽亦大矣！取妻，身迎，袨端為僕，秉轡授綏，如仰嚴親，昏禮威儀，如承祭祀。顛覆上下，悖逆父母，下則妻子，妻子上侵事親，若此可謂孝乎？儒者：「迎妻，妻之奉祭祀，子將守宗廟，故重之。」應之曰：「此誣言也，其宗兄守其先宗廟數十年，死喪之其，兄弟之妻奉其先之祭祀弗散，則喪妻子三年，必非以守奉祭祀也。夫憂妻子以大負絫，有曰『所以重親也』，為欲厚所至私，輕所至重，豈非大姦也哉！」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-1_s-1\",\n        \"mo-zi_ch-39_p-1_s-2\",\n        \"mo-zi_ch-39_p-1_s-3\",\n        \"mo-zi_ch-39_p-1_s-4\",\n        \"mo-zi_ch-39_p-1_s-5\",\n        \"mo-zi_ch-39_p-1_s-6\",\n        \"mo-zi_ch-39_p-1_s-7\",\n        \"mo-zi_ch-39_p-1_s-8\",\n        \"mo-zi_ch-39_p-1_s-9\",\n        \"mo-zi_ch-39_p-1_s-10\",\n        \"mo-zi_ch-39_p-1_s-11\",\n        \"mo-zi_ch-39_p-1_s-12\",\n        \"mo-zi_ch-39_p-1_s-13\",\n        \"mo-zi_ch-39_p-1_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"儒的人說道：親親有術，尊賢有等。言親疏尊卑的異啊。他的禮說道：喪父母三年，妻，後子三年，伯父叔父弟兄庶子他的，戚族人五月。若以親疏為歲月的數，則親的人多而且疏的人少矣，是妻後子與父同啊。若以尊卑為歲月數，則是尊他的妻子與父母同，而且親伯父宗兄而且卑子啊，逆孰大焉。他的親死，列屍弗斂，登屋窺井，挑鼠穴，探滌器，而且求他的人矣。以為客觀實體在則贛愚甚矣；如他的亡啊必求焉，偽亦大矣！取妻，身迎，袨端為僕，秉轡授綏，如仰嚴親，昏禮威儀，如承祭祀。顛覆上下，悖逆父母，下則妻子，妻子上侵事親，若此可謂孝乎？儒的人：迎妻，妻的奉祭祀，子將守宗廟，所以重的。應說道：此誣言啊，他的宗兄守他的先宗廟數十年，死喪的他的，兄弟的妻奉他的先的祭祀弗散，則喪妻子三年，必絕不是以守奉祭祀啊。夫憂妻子以大負絫，有說道：所以重親啊，為欲厚所至私，輕所至重，豈絕不是大姦啊哉！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「儒者曰：「親親有術，尊賢有等」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「儒」、「親」、「親」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「儒者曰親親有術尊賢有等言親疏尊卑之異也其禮曰喪父」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」言親疏尊卑之異也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-2\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 2,\n      \"canonicalText\": \"有強執有命以說議曰：「壽夭貧富，安危治亂，固有天命，不可損益。窮達賞罰幸否有極，人之知力，不能為焉。」羣吏信之，則怠於分職；庶人信之，則怠於從事。吏不治則亂，農事緩則貧，貧且亂政之本，而儒者以為道教，是賊天下之人者也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-2_s-1\",\n        \"mo-zi_ch-39_p-2_s-2\",\n        \"mo-zi_ch-39_p-2_s-3\",\n        \"mo-zi_ch-39_p-2_s-4\",\n        \"mo-zi_ch-39_p-2_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"有強執有命以推理說理議說道：壽夭貧富，安危治亂，固有天命，不可損益。窮達賞罰幸否有極，人的知力，不能為焉。羣吏信的，則怠於分職；庶人信的，則怠於從事。吏不治則亂，農事緩則貧，貧且亂政的本，而且儒的人以為道教，是賊天下的人的人啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「有強執有命以說議曰：「壽夭貧富，安危治亂，固有天命，不可損益」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「有」、「強」、「執」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「有強執有命以說議曰壽夭貧富安危治亂固有天命不可損」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「窮達賞罰幸否有極，人之知力，不能為焉」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 3,\n      \"canonicalText\": \"且夫繁飾禮樂以淫人，久喪偽哀以謾親，立命緩貧而高浩居，倍本棄事而安怠傲，貪於飲食，惰於作務，陷於飢寒，危於凍餒，無以違之。是若人氣，鼸鼠藏，而羝羊視，賁彘起。君子笑之。怒曰：「散人！焉知良儒。」夫夏乞麥禾，五穀既收，大喪是隨，子姓皆從，得厭飲食，畢治數喪，足以至矣。因人之家翠，以為，恃人之野以為尊，富人有喪，乃大說，喜曰：「此衣食之端也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-3_s-1\",\n        \"mo-zi_ch-39_p-3_s-2\",\n        \"mo-zi_ch-39_p-3_s-3\",\n        \"mo-zi_ch-39_p-3_s-4\",\n        \"mo-zi_ch-39_p-3_s-5\",\n        \"mo-zi_ch-39_p-3_s-6\",\n        \"mo-zi_ch-39_p-3_s-7\",\n        \"mo-zi_ch-39_p-3_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"再的人況且繁飾禮樂以淫人，久喪偽哀以謾親，立命緩貧而且高浩居，倍本棄事而且安怠傲，貪於飲食，惰於作務，陷於飢寒，危於凍餒，無以違的。是若人氣，鼸鼠藏，而且羝羊視，賁彘起。君子笑的。怒說道：散人！焉知良儒。夫夏乞麥禾，五穀既收，大喪是隨，子姓皆從，得厭飲食，畢治數喪，足以至矣。因人的家翠，以為，恃人的野以為尊，富人有喪，乃大推理說理，喜說道：此衣食的端啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「且夫繁飾禮樂以淫人，久喪偽哀以謾親，立命緩貧而高浩居，倍本棄事而安怠傲，貪於飲食，惰於作務，陷於飢寒，危於凍餒，無以違之」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「且」、「繁」、「飾」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「且夫繁飾禮樂以淫人久喪偽哀以謾親立命緩貧而高浩居」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「是若人氣，鼸鼠藏，而羝羊視，賁彘起」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-4\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 4,\n      \"canonicalText\": \"儒者曰：「君子必服古言然後仁。」應之曰：「所謂古之言服者，皆嘗新矣，而古人言之，服之，則非君子也。然則必服非君子之服，言非君子之言，而後仁乎？」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-4_s-1\",\n        \"mo-zi_ch-39_p-4_s-2\",\n        \"mo-zi_ch-39_p-4_s-3\",\n        \"mo-zi_ch-39_p-4_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"儒的人說道：君子必服古言然後仁。應說道：所謂古的言服的人，皆嘗新矣，而且古人言的，服的，則絕不是君子啊。然則必服絕不是君子的服，言絕不是君子的言，而且後仁乎？\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「儒者曰：「君子必服古言然後仁」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「儒」、「君」、「必」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「儒者曰君子必服古言然後仁應之曰所謂古之言服者皆嘗」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」應之曰：「所謂古之言服者，皆嘗新矣，而古人言之，服之，則非君子也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-5\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 5,\n      \"canonicalText\": \"又曰：「君子循而不作。」應之曰：「古者羿作弓，伃作甲，奚仲作車，巧垂作舟，然則今之鮑函車匠皆君子也，而羿、伃、奚仲、巧垂皆小人邪？且其所循人必或作之，然則其所循皆小人道也？」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-5_s-1\",\n        \"mo-zi_ch-39_p-5_s-2\",\n        \"mo-zi_ch-39_p-5_s-3\",\n        \"mo-zi_ch-39_p-5_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"又說道：君子循而且不作。應說道：古代羿作弓，伃作甲，奚仲作車，巧垂作舟，然則今的鮑函車匠皆君子啊，而且羿、伃、奚仲、巧垂皆小人邪？且他的所循人必或作的，然則他的所循皆小人道啊？\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「又曰：「君子循而不作」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「又」、「君」、「循」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「又曰君子循而不作應之曰古者羿作弓伃作甲奚仲作車巧」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」應之曰：「古者羿作弓，伃作甲，奚仲作車，巧垂作舟，然則今之鮑函車匠皆君子也，而羿、伃、奚仲、巧垂皆小人邪」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 6,\n      \"canonicalText\": \"又曰：「君子勝不逐奔，揜函弗射，施則助之胥車。」應之曰：「若皆仁人也，則無說而相與。仁人以其取捨是非之理相告，無故從有故也，弗知從有知也，無辭必服，見善必遷，何故相？若兩暴交爭，其勝者欲不逐奔，掩函弗射，施則助之胥車，雖盡能猶且不得為君子也。意暴殘之國也，聖將為世除害，興師誅罰，勝將因用儒術令士卒曰毋逐奔，揜函勿射，施則助之胥車。」暴亂之人也得活，天下害不除，是為羣殘父母，而深賤世也，不義莫大焉！」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-6_s-1\",\n        \"mo-zi_ch-39_p-6_s-2\",\n        \"mo-zi_ch-39_p-6_s-3\",\n        \"mo-zi_ch-39_p-6_s-4\",\n        \"mo-zi_ch-39_p-6_s-5\",\n        \"mo-zi_ch-39_p-6_s-6\",\n        \"mo-zi_ch-39_p-6_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"又說道：君子勝不逐奔，揜函弗射，施則助的胥車。應說道：若皆仁人啊，則無推理說理而且相與。仁人以他的取捨是絕不是的理相告，無所以從有所以啊，弗知從有知啊，無判斷命題必服，見善必遷，何所以相？若兩暴交爭，他的勝的人欲不逐奔，掩函弗射，施則助的胥車，雖盡能猶且不得為君子啊。意暴殘的國啊，聖將為世除害，興師誅罰，勝將因用儒術令士卒說道：毋逐奔，揜函勿射，施則助的胥車。暴亂的人啊得活，天下害不除，是為羣殘父母，而且深賤世啊，不義莫大焉！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「又曰：「君子勝不逐奔，揜函弗射，施則助之胥車」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「又」、「君」、「勝」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「又曰君子勝不逐奔揜函弗射施則助之胥車應之曰若皆仁」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」應之曰：「若皆仁人也，則無說而相與」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 7,\n      \"canonicalText\": \"又曰：「君子若鍾，擊之則鳴，弗擊不鳴。應之曰：「夫仁人事上竭忠，事親得孝，務善則美，有過則諫，此為人臣之道也。今擊之則鳴，弗擊不鳴，隱知豫力，恬漠待問而後對，雖有君親之大利，弗問不言，若將有大寇亂，盜賊將作，若機闢將發也，他人不知，己獨知之，雖其君親皆在，不問不言。是夫大亂之賊也！以是為人臣不忠，為子不孝，事兄不弟，交，遇人不貞良。夫執後不言之朝物，見利使己雖恐後言，君若言而未有利焉，則高拱下視，會噎為深，曰：『唯其未之學也。』用誰急，遺行遠矣。夫一道術學業仁義者，皆大以治人，小以任官，遠施周偏，近以脩身，不義不處，非理不行，務興天下之利，曲直周旋，利則止，此君子之道也。以所聞孔丘之行，則本與此相反謬也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-7_s-1\",\n        \"mo-zi_ch-39_p-7_s-2\",\n        \"mo-zi_ch-39_p-7_s-3\",\n        \"mo-zi_ch-39_p-7_s-4\",\n        \"mo-zi_ch-39_p-7_s-5\",\n        \"mo-zi_ch-39_p-7_s-6\",\n        \"mo-zi_ch-39_p-7_s-7\",\n        \"mo-zi_ch-39_p-7_s-8\",\n        \"mo-zi_ch-39_p-7_s-9\",\n        \"mo-zi_ch-39_p-7_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"又說道：君子若鍾，擊的則鳴，弗擊不鳴。應說道：夫仁人事上竭忠，事親得孝，務善則美，有過則諫，此為人臣的道啊。今擊的則鳴，弗擊不鳴，隱知豫力，恬漠待問而且後對，雖有君親的大利，弗問不言，若將有大寇亂，盜賊將作，若機闢將發啊，他人不知，己獨知的，雖他的君親皆在，不問不言。是夫大亂的賊啊！以是為人臣不忠，為子不孝，事兄不弟，交，遇人不貞良。夫執後不言的朝物，見利使己雖恐後言，君若言而且未有利焉，則高拱下視，會噎為深，說道：唯他的未的學啊。用誰急，遺行遠矣。夫一道術學業仁義的人，皆大以治人，小以任官，遠施周偏，近以脩身，不義不處，絕不是理不行，務興天下的利，曲直周旋，利則止，此君子的道啊。以所聞孔丘的行，則本與此相反謬啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「又曰：「君子若鍾，擊之則鳴，弗擊不鳴」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「又」、「君」、「鍾」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「又曰君子若鍾擊之則鳴弗擊不鳴應之曰夫仁人事上竭忠」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「應之曰：「夫仁人事上竭忠，事親得孝，務善則美，有過則諫，此為人臣之道也」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 8,\n      \"canonicalText\": \"齊景公問晏子曰：「孔子為人何如？」晏子不對，公又復問，不對。景公曰：「以孔丘語寡人者眾矣，俱以賢人也。今寡人問之，而子不對，何也？」晏子對曰：「嬰不肖，不足以知賢人。雖然，嬰聞所謂賢人者，入人之國必務合其君臣之親，而弭其上下之怨。孔丘之荊，知白公之謀，而奉之以石乞，君身幾滅，而白公僇。嬰聞賢人得上不虛，得下不危，言聽於君必利人，教行下必於上，是以言明而易知也，行明而易從也，行義可明乎民，謀慮可通乎君臣。今孔丘深慮同謀以奉賊，勞思盡知以行邪，勸下亂上，教臣殺君，非賢人之行也；入人之國而與人之賊，非義之類也；知人不忠，趣之為亂，非仁義之也。逃人而後謀，避人而後言，行義不可明於民，謀慮不可通於君臣，嬰不知孔丘之有異於白公也，是以不對。」景公曰：「嗚乎！貺寡人者眾矣，非夫子，則吾終身不知孔丘之與白公同也。」\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-8_s-1\",\n        \"mo-zi_ch-39_p-8_s-2\",\n        \"mo-zi_ch-39_p-8_s-3\",\n        \"mo-zi_ch-39_p-8_s-4\",\n        \"mo-zi_ch-39_p-8_s-5\",\n        \"mo-zi_ch-39_p-8_s-6\",\n        \"mo-zi_ch-39_p-8_s-7\",\n        \"mo-zi_ch-39_p-8_s-8\",\n        \"mo-zi_ch-39_p-8_s-9\",\n        \"mo-zi_ch-39_p-8_s-10\",\n        \"mo-zi_ch-39_p-8_s-11\",\n        \"mo-zi_ch-39_p-8_s-12\",\n        \"mo-zi_ch-39_p-8_s-13\",\n        \"mo-zi_ch-39_p-8_s-14\",\n        \"mo-zi_ch-39_p-8_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"齊景公問晏子說道：孔子為人何如？晏子不對，公又復問，不對。景公說道：以孔丘語寡人的人眾矣，俱以賢人啊。今寡人問的，而且子不對，何啊？晏子對說道：嬰不肖，不足以知賢人。雖然，嬰聞所謂賢人的人，入人的國必務合他的君臣的親，而且弭他的上下的怨。孔丘的荊，知白公的謀，而且奉的以石乞，君身幾滅，而且白公僇。嬰聞賢人得上不虛，得下不危，言聽於君必利人，教行下必於上，是以言明而且易知啊，行明而且易從啊，行義可明乎民，謀慮可通乎君臣。今孔丘深慮同謀以奉賊，勞思盡知以行邪，勸下亂上，教臣殺君，絕不是賢人的行啊；入人的國而且與人的賊，絕不是義的類啊；知人不忠，趣的為亂，絕不是仁義的啊。逃人而且後謀，避人而且後言，行義不可明於民，謀慮不可通於君臣，嬰不知孔丘的有異於白公啊，是以不對。景公說道：嗚乎！貺寡人的人眾矣，絕不是夫子，則吾終身不知孔丘的與白公同啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「齊景公問晏子曰：「孔子為人何如」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「齊」、「景」、「公」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「齊景公問晏子曰孔子為人何如晏子不對公又復問不對景」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「」晏子不對，公又復問，不對」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 9,\n      \"canonicalText\": \"孔丘之齊見景公，景公說，欲封之以尼谿，以告晏子。晏子曰：「不可夫儒浩居而自順者也，不可以教下；好樂而淫人，不可使親治；立命而怠事，不可使守職；宗喪循哀，不可使慈民；機服勉容，不可使導眾。孔丘盛容脩飾以蠱世，絃歌鼓舞以聚徒，繁登降之禮以示儀，務趨翔之節以觀眾，博學不可使議世，勞思不可以補民，絫壽不能盡其學，當年不能行其禮，積財不能贍其樂，繁飾邪術以營世君，盛為聲樂以淫遇民，其道不可以期世，其學不可以導眾。今君封之，以利齊俗，非所以導國先眾。」公曰：「善！」於是厚其禮，留其封，敬見而不問其道。孔丘乃恚，怒於景公與晏子，乃樹鴟夷子皮於田常之門，告南郭惠子以所欲為，歸於魯。有頃，閒齊將伐魯，告子貢曰：「賜乎！舉大事於今之時矣！」乃遣子貢之齊，因南郭惠子以見田常，勸之伐吳，以教高、國、鮑、晏，使毋得害田常之亂，勸越伐吳。三年之內，齊、吳破國之難，伏屍以言術數。孔丘之誅也。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-9_s-1\",\n        \"mo-zi_ch-39_p-9_s-2\",\n        \"mo-zi_ch-39_p-9_s-3\",\n        \"mo-zi_ch-39_p-9_s-4\",\n        \"mo-zi_ch-39_p-9_s-5\",\n        \"mo-zi_ch-39_p-9_s-6\",\n        \"mo-zi_ch-39_p-9_s-7\",\n        \"mo-zi_ch-39_p-9_s-8\",\n        \"mo-zi_ch-39_p-9_s-9\",\n        \"mo-zi_ch-39_p-9_s-10\",\n        \"mo-zi_ch-39_p-9_s-11\",\n        \"mo-zi_ch-39_p-9_s-12\",\n        \"mo-zi_ch-39_p-9_s-13\",\n        \"mo-zi_ch-39_p-9_s-14\",\n        \"mo-zi_ch-39_p-9_s-15\",\n        \"mo-zi_ch-39_p-9_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔丘的齊見景公，景公推理說理，欲封的以尼谿，以告晏子。晏子說道：不可夫儒浩居而且自順的人啊，不可以教下；好樂而且淫人，不可使親治；立命而且怠事，不可使守職；宗喪循哀，不可使慈民；機服勉容，不可使導眾。孔丘盛容脩飾以蠱世，絃歌鼓舞以聚徒，繁登降的禮以示儀，務趨翔的節以觀眾，博學不可使議世，勞思不可以補民，絫壽不能盡他的學，當年不能行他的禮，積財不能贍他的樂，繁飾邪術以營世君，盛為聲樂以淫遇民，他的道不可以期世，他的學不可以導眾。今君封的，以利齊俗，絕不是所以導國先眾。公說道：善！於是厚他的禮，留他的封，敬見而且不問他的道。孔丘乃恚，怒於景公與晏子，乃樹鴟夷子皮於田常的門，告南郭惠子以所欲為，歸於魯。有頃，閒齊將伐魯，告子貢說道：賜乎！舉大事於今的時矣！乃遣子貢的齊，因南郭惠子以見田常，勸的伐吳，以教高、國、鮑、晏，使毋得害田常的亂，勸越伐吳。三年的內，齊、吳破國的難，伏屍以言術數。孔丘的誅啊。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「孔丘之齊見景公，景公說，欲封之以尼谿，以告晏子」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「孔」、「丘」、「齊」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「孔丘之齊見景公景公說欲封之以尼谿以告晏子晏子曰不」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「晏子曰：「不可夫儒浩居而自順者也，不可以教下」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-10\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 10,\n      \"canonicalText\": \"孔丘為魯司寇，舍公家而奉季孫。季孫相魯君而走，季孫與邑人爭門關，決植。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-10_s-1\",\n        \"mo-zi_ch-39_p-10_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔子當年擔任魯國司寇之時，置魯國公室利益於不顧，反而竭力逢迎侍奉權臣季孫氏。季孫氏輔佐魯定公與齊國作戰失敗而倉皇出逃，季孫氏與守城門的百姓爭奪關閉城門的控制權，甚至親自拔掉阻擋城門的木栓逃命。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「孔丘為魯司寇，舍公家而奉季孫」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「孔」、「丘」、「為」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「孔丘為魯司寇舍公家而奉季孫季孫相魯君而走季孫與邑」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「季孫相魯君而走，季孫與邑人爭門關，決植」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 11,\n      \"canonicalText\": \"孔丘窮於蔡陳之閒，藜羹不糝，十日，子路為享豚，孔丘不問肉之所由來而食；號人衣以酤酒，孔丘不問酒之所由來而飲。哀公迎孔子，席不端弗坐，割不正弗食，子路進，請曰：「何其與陳、蔡反也？」孔丘曰：「來！吾語女，曩與女為苟生，今與女為苟義。」夫飢約則不辭妄取，以活身，贏飽則偽行以自飾，汙邪詐偽，孰大於此！\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-11_s-1\",\n        \"mo-zi_ch-39_p-11_s-2\",\n        \"mo-zi_ch-39_p-11_s-3\",\n        \"mo-zi_ch-39_p-11_s-4\",\n        \"mo-zi_ch-39_p-11_s-5\",\n        \"mo-zi_ch-39_p-11_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔丘窮於蔡陳的閒，藜羹不糝，十日，子路為享豚，孔丘不問肉的所由來而且食；號人衣以酤酒，孔丘不問酒的所由來而且飲。哀公迎孔子，席不端弗坐，割不正弗食，子路進，請說道：何他的與陳、蔡反啊？孔丘說道：來！吾語女，曩與女為苟生，今與女為苟義。夫飢約則不判斷命題妄取，以活身，贏飽則偽行以自飾，汙邪詐偽，孰大於此！\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「孔丘窮於蔡陳之閒，藜羹不糝，十日，子路為享豚，孔丘不問肉之所由來而食」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「孔」、「丘」、「窮」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「孔丘窮於蔡陳之閒藜羹不糝十日子路為享豚孔丘不問肉」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「號人衣以酤酒，孔丘不問酒之所由來而飲」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"order\": 12,\n      \"canonicalText\": \"孔丘與其門弟子閒坐，曰：「夫舜見瞽叟孰然，此時天下圾乎！周公旦非其人也邪？何為舍其家室而託寓也？」孔丘所行，心術所至也。其徒屬弟子皆效孔丘。子貢、季路輔孔悝亂乎衛，陽貨亂乎齊，佛肸以中牟叛，桼雕刑殘，莫大焉。夫為弟子後生，其師，必脩其言，法其行，力不足，知弗及而後已。今孔丘之行如此，儒士則可以疑矣。\",\n      \"sentenceIds\": [\n        \"mo-zi_ch-39_p-12_s-1\",\n        \"mo-zi_ch-39_p-12_s-2\",\n        \"mo-zi_ch-39_p-12_s-3\",\n        \"mo-zi_ch-39_p-12_s-4\",\n        \"mo-zi_ch-39_p-12_s-5\",\n        \"mo-zi_ch-39_p-12_s-6\",\n        \"mo-zi_ch-39_p-12_s-7\",\n        \"mo-zi_ch-39_p-12_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《墨子》—中國哲學書電子化計劃\",\n          \"edition\": \"孫詒讓《墨子閒詁》本\",\n          \"location\": \"https://ctext.org/mozi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《墨子》—維基文庫\",\n          \"edition\": \"四部叢刊景明正統道藏本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/墨子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"孔丘與他的門弟子閒坐，說道：夫舜見瞽叟孰然，此時天下圾乎！周公旦絕不是他的人啊邪？何為舍他的家室而且託寓啊？孔丘所行，心術所至啊。他的徒屬弟子皆效孔丘。子貢、季路輔孔悝亂乎衛，陽貨亂乎齊，佛肸以中牟叛，桼雕刑殘，莫大焉。夫為弟子後生，他的師，必脩他的言，法他的行，力不足，知弗及而且後已。今孔丘的行如此，儒士則可以疑矣。\",\n        \"analysis\": \"【墨學篇旨與核心哲思】\\n本節選自先秦平民哲學顯學名篇《墨子》〈非儒下〉。墨子學派以兼愛天下為宗，開篇「孔丘與其門弟子閒坐，曰：「夫舜見瞽叟孰然，此時天下圾乎」直擊戰國亂世社會疾苦，彰顯興天下之利、除天下之害之救世熱忱。\\n\\n【名辯邏輯與科技守城訓詁】\\n依清孫詒讓《墨子閒詁》與現代吳毓江《墨子校注》，深究「孔」、「丘」、「門」等墨家核心綱領與名辯術語，辨名審實，將認識論、三表法與工程守備智慧融會貫通。\\n\\n【嚴密思辨與章法論證】\\n全文邏輯嚴密深沉，引述「孔丘與其門弟子閒坐曰夫舜見瞽叟孰然此時天下圾乎周」層層論辯，言必有三表（上本之先王、下原察百姓、發而為刑政），以功利實效與百姓生計為衡量尺度，說理透徹，文氣剛健篤實。\\n\\n【兼愛交利之崇高實踐】\\n「周公旦非其人也邪」生動體現摩頂放踵利天下為之之博大情懷，反對不義侵略與奢靡浪費，為弱小百姓爭取和平生存空間，樹立中華文化最具實踐力與平民光輝之崇高典範。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"儒者曰：「親親有術，尊賢有等。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"」言親疏尊卑之異也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"其禮曰：「喪父母三年，妻，後子三年，伯父叔父弟兄庶子其，戚族人五月。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"」若以親疏為歲月之數，則親者多而疏者少矣，是妻後子與父同也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"若以尊卑為歲月數，則是尊其妻子與父母同，而親伯父宗兄而卑子也，逆孰大焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"其親死，列屍弗斂，登屋窺井，挑鼠穴，探滌器，而求其人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"以為實在則贛愚甚矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"如其亡也必求焉，偽亦大矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"取妻，身迎，袨端為僕，秉轡授綏，如仰嚴親，昏禮威儀，如承祭祀。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"顛覆上下，悖逆父母，下則妻子，妻子上侵事親，若此可謂孝乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"儒者：「迎妻，妻之奉祭祀，子將守宗廟，故重之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 12,\n      \"canonicalText\": \"」應之曰：「此誣言也，其宗兄守其先宗廟數十年，死喪之其，兄弟之妻奉其先之祭祀弗散，則喪妻子三年，必非以守奉祭祀也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 13,\n      \"canonicalText\": \"夫憂妻子以大負絫，有曰『所以重親也』，為欲厚所至私，輕所至重，豈非大姦也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-1_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-1\",\n      \"order\": 14,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-2_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"有強執有命以說議曰：「壽夭貧富，安危治亂，固有天命，不可損益。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-2_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"窮達賞罰幸否有極，人之知力，不能為焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-2_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"」羣吏信之，則怠於分職；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-2_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"庶人信之，則怠於從事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-2_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"吏不治則亂，農事緩則貧，貧且亂政之本，而儒者以為道教，是賊天下之人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"且夫繁飾禮樂以淫人，久喪偽哀以謾親，立命緩貧而高浩居，倍本棄事而安怠傲，貪於飲食，惰於作務，陷於飢寒，危於凍餒，無以違之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"是若人氣，鼸鼠藏，而羝羊視，賁彘起。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"君子笑之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"怒曰：「散人！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"焉知良儒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"」夫夏乞麥禾，五穀既收，大喪是隨，子姓皆從，得厭飲食，畢治數喪，足以至矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"因人之家翠，以為，恃人之野以為尊，富人有喪，乃大說，喜曰：「此衣食之端也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-3_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-4_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"儒者曰：「君子必服古言然後仁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-4_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"」應之曰：「所謂古之言服者，皆嘗新矣，而古人言之，服之，則非君子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-4_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"然則必服非君子之服，言非君子之言，而後仁乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-4_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-5_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"又曰：「君子循而不作。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-5_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"」應之曰：「古者羿作弓，伃作甲，奚仲作車，巧垂作舟，然則今之鮑函車匠皆君子也，而羿、伃、奚仲、巧垂皆小人邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-5_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"且其所循人必或作之，然則其所循皆小人道也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-5_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"又曰：「君子勝不逐奔，揜函弗射，施則助之胥車。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"」應之曰：「若皆仁人也，則無說而相與。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"仁人以其取捨是非之理相告，無故從有故也，弗知從有知也，無辭必服，見善必遷，何故相？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"若兩暴交爭，其勝者欲不逐奔，掩函弗射，施則助之胥車，雖盡能猶且不得為君子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"意暴殘之國也，聖將為世除害，興師誅罰，勝將因用儒術令士卒曰毋逐奔，揜函勿射，施則助之胥車。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"」暴亂之人也得活，天下害不除，是為羣殘父母，而深賤世也，不義莫大焉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-6_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"又曰：「君子若鍾，擊之則鳴，弗擊不鳴。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"應之曰：「夫仁人事上竭忠，事親得孝，務善則美，有過則諫，此為人臣之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"今擊之則鳴，弗擊不鳴，隱知豫力，恬漠待問而後對，雖有君親之大利，弗問不言，若將有大寇亂，盜賊將作，若機闢將發也，他人不知，己獨知之，雖其君親皆在，不問不言。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"是夫大亂之賊也！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"以是為人臣不忠，為子不孝，事兄不弟，交，遇人不貞良。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"夫執後不言之朝物，見利使己雖恐後言，君若言而未有利焉，則高拱下視，會噎為深，曰：『唯其未之學也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"』用誰急，遺行遠矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"夫一道術學業仁義者，皆大以治人，小以任官，遠施周偏，近以脩身，不義不處，非理不行，務興天下之利，曲直周旋，利則止，此君子之道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"以所聞孔丘之行，則本與此相反謬也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-7_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-7\",\n      \"order\": 10,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"齊景公問晏子曰：「孔子為人何如？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"」晏子不對，公又復問，不對。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"景公曰：「以孔丘語寡人者眾矣，俱以賢人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"今寡人問之，而子不對，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"」晏子對曰：「嬰不肖，不足以知賢人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"雖然，嬰聞所謂賢人者，入人之國必務合其君臣之親，而弭其上下之怨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"孔丘之荊，知白公之謀，而奉之以石乞，君身幾滅，而白公僇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"嬰聞賢人得上不虛，得下不危，言聽於君必利人，教行下必於上，是以言明而易知也，行明而易從也，行義可明乎民，謀慮可通乎君臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"今孔丘深慮同謀以奉賊，勞思盡知以行邪，勸下亂上，教臣殺君，非賢人之行也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"入人之國而與人之賊，非義之類也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"知人不忠，趣之為亂，非仁義之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 12,\n      \"canonicalText\": \"逃人而後謀，避人而後言，行義不可明於民，謀慮不可通於君臣，嬰不知孔丘之有異於白公也，是以不對。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 13,\n      \"canonicalText\": \"」景公曰：「嗚乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 14,\n      \"canonicalText\": \"貺寡人者眾矣，非夫子，則吾終身不知孔丘之與白公同也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-8_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-8\",\n      \"order\": 15,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"孔丘之齊見景公，景公說，欲封之以尼谿，以告晏子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"晏子曰：「不可夫儒浩居而自順者也，不可以教下；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"好樂而淫人，不可使親治；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"立命而怠事，不可使守職；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"宗喪循哀，不可使慈民；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"機服勉容，不可使導眾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"孔丘盛容脩飾以蠱世，絃歌鼓舞以聚徒，繁登降之禮以示儀，務趨翔之節以觀眾，博學不可使議世，勞思不可以補民，絫壽不能盡其學，當年不能行其禮，積財不能贍其樂，繁飾邪術以營世君，盛為聲樂以淫遇民，其道不可以期世，其學不可以導眾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"今君封之，以利齊俗，非所以導國先眾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-9\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"」公曰：「善！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-10\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 10,\n      \"canonicalText\": \"」於是厚其禮，留其封，敬見而不問其道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-11\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 11,\n      \"canonicalText\": \"孔丘乃恚，怒於景公與晏子，乃樹鴟夷子皮於田常之門，告南郭惠子以所欲為，歸於魯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-12\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 12,\n      \"canonicalText\": \"有頃，閒齊將伐魯，告子貢曰：「賜乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-13\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 13,\n      \"canonicalText\": \"舉大事於今之時矣！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-14\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 14,\n      \"canonicalText\": \"」乃遣子貢之齊，因南郭惠子以見田常，勸之伐吳，以教高、國、鮑、晏，使毋得害田常之亂，勸越伐吳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-15\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 15,\n      \"canonicalText\": \"三年之內，齊、吳破國之難，伏屍以言術數。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-9_s-16\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-9\",\n      \"order\": 16,\n      \"canonicalText\": \"孔丘之誅也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-10_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"孔丘為魯司寇，舍公家而奉季孫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-10_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"季孫相魯君而走，季孫與邑人爭門關，決植。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"孔丘窮於蔡陳之閒，藜羹不糝，十日，子路為享豚，孔丘不問肉之所由來而食；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"號人衣以酤酒，孔丘不問酒之所由來而飲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"哀公迎孔子，席不端弗坐，割不正弗食，子路進，請曰：「何其與陳、蔡反也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"」孔丘曰：「來！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"吾語女，曩與女為苟生，今與女為苟義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-11_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"」夫飢約則不辭妄取，以活身，贏飽則偽行以自飾，汙邪詐偽，孰大於此！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-1\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"孔丘與其門弟子閒坐，曰：「夫舜見瞽叟孰然，此時天下圾乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-2\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"周公旦非其人也邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-3\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"何為舍其家室而託寓也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-4\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"」孔丘所行，心術所至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-5\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"其徒屬弟子皆效孔丘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-6\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"子貢、季路輔孔悝亂乎衛，陽貨亂乎齊，佛肸以中牟叛，桼雕刑殘，莫大焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-7\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"夫為弟子後生，其師，必脩其言，法其行，力不足，知弗及而後已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"mo-zi_ch-39_p-12_s-8\",\n      \"workId\": \"mo-zi\",\n      \"chapterId\": \"mo-zi_ch-39\",\n      \"passageId\": \"mo-zi_ch-39_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"今孔丘之行如此，儒士則可以疑矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
